def calculate_discount(price: float, percent: float) -> float:
    """Return discounted price."""
    if price < 0:
        raise ValueError("price must be non-negative")
    # BUG: 100% should be valid, but this condition rejects it.
    if percent < 0 or percent >= 100:
        raise ValueError("percent must be between 0 and 100")
    return round(price * (1 - percent / 100), 2)

from pricing import calculate_discount

def test_regular_discount():
    assert calculate_discount(200, 25) == 150.0

def test_full_discount_is_allowed():
    assert calculate_discount(250, 100) == 0.0

from pricing import calculate_discount

def checkout_total(items, coupon_percent=0):
    subtotal = sum(float(item["price"]) * int(item.get("qty", 1)) for item in items)
    return calculate_discount(subtotal, coupon_percent)
